#include "gui/control_layout.hpp"
#include <algorithm>
#include <cmath>

namespace epochengine::gui_lib {
ButtonLayout update_button(ButtonState& s,Rect b,const ButtonInput& i) noexcept {ButtonLayout l{};l.bounds=b;l.hovered=contains(b,i.mouse_position);if(i.mouse_pressed&&l.hovered)s.held=true;if(i.mouse_released){l.activated=s.held&&l.hovered;s.held=false;}l.held=s.held;return l;}
ToggleLayout update_toggle(bool& value,Rect b,const ButtonInput& i) noexcept {ToggleLayout l{};l.bounds=b;l.track={{b.position.x+b.size.x-38.0f,b.position.y+(b.size.y-18.0f)*.5f},{34,18}};l.hovered=contains(b,i.mouse_position);if(i.mouse_released&&l.hovered){value=!value;l.changed=true;}l.value=value;l.thumb={{l.track.position.x+(value?17.0f:1.0f),l.track.position.y+1.0f},{16,16}};return l;}
SliderLayout update_slider(SliderState& s,float& value,float minimum,float maximum,Rect b,const ButtonInput& i) noexcept {SliderLayout l{};l.bounds=b;l.track={{b.position.x,b.position.y+b.size.y*.5f-2},{b.size.x,4}};l.hovered=contains(b,i.mouse_position);if(i.mouse_pressed&&l.hovered)s.dragging=true;if(i.mouse_released)s.dragging=false;if(s.dragging&&i.mouse_down&&maximum>minimum){const float f=std::clamp((i.mouse_position.x-b.position.x)/(std::max)(1.0f,b.size.x),0.0f,1.0f);const float next=minimum+(maximum-minimum)*f;l.changed=std::abs(next-value)>1e-6f;value=next;}l.fraction=maximum>minimum?std::clamp((value-minimum)/(maximum-minimum),0.0f,1.0f):0;l.fill=l.track;l.fill.size.x*=l.fraction;l.thumb={{l.track.position.x+l.track.size.x*l.fraction-5,l.track.position.y-3},{10,10}};return l;}
SegmentedControlLayout make_segmented_control_layout(const SegmentedControlLayoutOptions& o) noexcept {SegmentedControlLayout l{};l.item_count=o.item_count;l.height=(std::max)(1.0f,o.height);l.gap=(std::max)(0.0f,o.gap);float w=0;for(std::uint32_t i=0;i<o.item_count;++i)w+=(std::max)(1.0f,o.item_widths[i]);if(o.item_count>1)w+=l.gap*(o.item_count-1);l.bounds={o.position,{w,l.height}};l.valid=o.item_widths&&o.item_count>0;return l;}
Rect segmented_control_item_layout(const SegmentedControlLayoutOptions& o,std::uint32_t index) noexcept {const auto l=make_segmented_control_layout(o);if(!l.valid||index>=o.item_count)return{};float x=o.position.x;for(std::uint32_t i=0;i<index;++i)x+=(std::max)(1.0f,o.item_widths[i])+l.gap;return{{x,o.position.y},{(std::max)(1.0f,o.item_widths[index]),l.height}};}
std::uint32_t segmented_control_item_at(const SegmentedControlLayoutOptions& o,Vec2 p) noexcept {const auto l=make_segmented_control_layout(o);if(!l.valid||!contains(l.bounds,p))return 0xffffffffU;for(std::uint32_t i=0;i<o.item_count;++i)if(contains(segmented_control_item_layout(o,i),p))return i;return 0xffffffffU;}
}
